patches.new:
top->ddr_r_valid = 0;
if (mem_q.empty()) return;
// AXI allows R interleaving across different IDs. Promote only the
// oldest DS request, retaining order within every ID and preserving
// a VALID payload held from the prior tick. No DUT arbitration changes.
// Each request retains its original latency/beat state after rotation.
bool ds_promoted = false;
if (ds_priority && win_open && !ddr_r_held &&
    ((mem_q.front().id >> 4) & 3) != 3) {
    auto ds = std::find_if(mem_q.begin(), mem_q.end(), [](const MemRead& r) {
        return ((r.id >> 4) & 3) == 3;
    });
    if (ds != mem_q.end()) {
        std::rotate(mem_q.begin(), ds, ds + 1);
        ds_promoted = true;
    }
}
// +memory-r-interleave=1: at a beat boundary, rotate the next ready
// distinct AXI ID to the head.  Only the oldest outstanding AR for an
// ID is eligible, so same-ID AR order is preserved.  A held VALID
// payload is never rotated (ddr_r_held), so the first offered beat
// stays stable until accepted.
if (memory_r_interleave && !ddr_r_held && !ds_promoted) {
    size_t sel = mem_q.size();
    uint8_t sel_id = 0;
    for (unsigned step = 1; step <= 64; ++step) {
        const uint8_t cand = (uint8_t)((r_rr_last_id + step) & 0x3f);
        size_t idx = mem_q.size();
        for (size_t i = 0; i < mem_q.size(); ++i) {
            if ((uint8_t)mem_q[i].id == cand) { idx = i; break; }
        }
        if (idx < mem_q.size() &&
            g_cycle > mem_q[idx].accepted_cycle + (long)ptw_latency) {
            sel = idx; sel_id = cand; break;
        }
    }
    if (sel < mem_q.size()) {
        if (sel != 0)
            std::rotate(mem_q.begin(), mem_q.begin() + (long)sel,
                        mem_q.begin() + (long)sel + 1);
        r_rr_last_id = sel_id;
    }
}
MemRead& h = mem_q.front();
ddr_setup_port = (h.id >> 4) & 3u;
if (memory_r_interleave) {
    // Interleave mode uses the same per-request acceptance latency as
    // the existing overlap model; the serial countdown is unchanged
    // when this flag is 0.
    if (g_cycle <= h.accepted_cycle + (long)ptw_latency) {
        ddr_setup_wait = true;
        return;
    }
} else if (read_latency_overlap && measurement_phase) {
    // Same isolated-request delay as the old model: AR accepted at
    // t first returns at t + latency + 1. Queued requests age from
    // acceptance, allowing their preparation delays to overlap.
    if (g_cycle <= h.accepted_cycle + (long)ptw_latency) {
        ddr_setup_wait = true;
        return;
    }
} else if (h.latency > 0) {
    --h.latency;
    ddr_setup_wait = true;
    return;
}
